dict.string:
((input) => {
  const cap = 32
  const clipEnd = s => (s = s ?? "", s.length > cap ? s.slice(0, cap - 1) + "…" : s)
  const clipMid = s => {
    s = s ?? ""
    if (s.length <= cap) return s
    const head = Math.floor((cap - 1) / 2), tail = (cap - 1) - head
    return s.slice(0, head) + "…" + s.slice(-tail)
  }
  const F = [..."𝙖𝙗𝙘𝙙𝙚𝙛𝙜𝙝𝙞𝙟𝙠𝙡𝙢𝙣𝙤𝙥𝙦𝙧𝙨𝙩𝙪𝙫𝙬𝙭𝙮𝙯"]
  const sans = s => String(s).toLowerCase().replace(/[a-z]/g, c => F[c.charCodeAt(0) - 97] || c)
  const sup = d => d === "0" ? "⁰" : "¹²³⁴⁵⁶⁷⁸⁹"[d.charCodeAt(0) - 49]
  const supNum = x => String(x).replace(/\d/g, d => sup(d))
  const supTag = x => "⁽" + supNum(x) + "⁾"
  const rpad = (s, w) => s + " ".repeat(Math.max(0, w - s.length))

  const RULES = {
    "icloud.com/shortcuts": "shortcut",
    "lawfilesext.leg.wa.gov": "lawfiles",
    "shortcuts://open-shortcut": "open shortcut",
    "shortcuts://run-shortcut": "run shortcut",
    "http": "URL"
  }
  const classifyUrl = u => {
    const hay = u.toLowerCase()
    const match = Object.entries(RULES).find(([k]) => hay.includes(k))
    return match ? match[1] : "URL"
  }
  const looksUrl = s => /^(https?:\/\/|shortcuts:\/\/)\S+$/i.test(s)

  const decodeB64 = b64 => {
    try {
      return new TextDecoder().decode(
        Uint8Array.from(atob(b64.replace(/\s+/g, "")), c => c.charCodeAt(0))
      )
    } catch (e) { return "" }
  }

  const transformOne = o => {
    const base64 = String(o["Base64"] || "")
    const count = Number(o["Count"] || 0) || 0
    const isList = count > 1

    const first = base64.split(/\r?\n/)[0] || ""
    const preview = first.slice(0, 10) + (first.length > 10 ? "…" : "")

    const rawType = String(o["Type"] || "")
    const name = String(o["Name"] || "")
    const ext  = String(o["File Extension"] || "")

    // Decode once. List items don't carry a single payload, so skip it there.
    const decoded = isList ? "" : decodeB64(base64)

    // A URL is either declared in the URL field, or it's the entire text payload.
    const fieldUrl = String(o["URL"] || "")
    const textUrl = (!isList && !fieldUrl && looksUrl(decoded.trim())) ? decoded.trim() : ""
    const url = fieldUrl || textUrl
    const isUrlItem = url.length > 0

    const fileName = isList ? "LIST"
      : isUrlItem ? (name || url)
      : (ext ? (name ? (name + "." + ext) : ("." + ext)) : name)

    let type
    if (isList) {
      const exts = ext.split(/\r?\n/).map(s => s.trim()).filter(Boolean)
      let tagLabel = "mixed"
      if (exts.length) {
        const e0 = exts[0]
        let same = true
        for (const e of exts) if (e !== e0) { same = false; break }
        if (same) tagLabel = e0
      }
      type = "List (" + tagLabel + ")"
    } else if (isUrlItem) {
      type = classifyUrl(url)
    } else if (ext.toLowerCase() === "skill") {
      type = "skill"
    } else if (first.startsWith("YnBsa")) {
      type = "Action"
    } else {
      type = rawType
    }

    const urlTypes = ["URL", "shortcut", "open shortcut", "run shortcut", "lawfiles"]
    const isUrl = urlTypes.includes(type)
    const icon = isList ? "📇 " : (isUrl ? "🔗 " : (type === "skill" ? "🧩 " : "🧾 "))
    const inner = icon + sans(type || "item")
    const W = 68, baseStr = "- " + inner + " -"
    const header = " ".repeat(Math.max(0, Math.floor((W - baseStr.length) / 2) + 2)) + baseStr

    let lines
    if (isList) {
      const names = name.split(/\r?\n/).map(s => s.trim())
      const exts  = ext.split(/\r?\n/).map(s => s.trim())
      const n = Math.max(count || 0, names.length, exts.length, 0)
      lines = []
      for (let i = 0; i < n; i++) {
        const nm = names[i] || ""
        const ex = exts[i] || ""
        let fn = ex ? (nm ? (nm + "." + ex) : ("." + ex)) : nm
        if (!fn) fn = "Item " + (i + 1)
        lines.push(fn)
      }
      if (!lines.length) lines = ["LIST"]
    } else if (isUrlItem) {
      lines = [name || "", url].filter(Boolean)
      if (!lines.length) lines = ["URL"]
    } else {
      let textLines = null
      const looksBinary = !decoded || /[\x00-\x08\x0E-\x1F]/.test(decoded.slice(0, 200))
      if (!looksBinary) {
        textLines = decoded.split(/\r?\n/)
        while (textLines.length && !textLines[textLines.length - 1]) textLines.pop()
      }
      lines = (textLines && textLines.length) ? textLines : [fileName || "Item"]
    }

    const n = lines.length || 1
    const Lw = supTag(n).length
    const mid = lines.length <= 2 ? "" : clipEnd(lines.slice(1, -1).join("\n").replace(/\r?\n/g, "␤"))
    const row = i => rpad(supTag(i), Lw) + " " + clipMid(lines[i - 1] || "")
    const body = [row(1), n == 2 ? row(2) : n > 2 ? ("⋯" + (mid ? " " + mid : "")) : null, n > 2 ? row(n) : null].filter(Boolean).join("\n")

    const detail = { type, fileName, preview, caption: header + "\n" + body }
    if (isUrlItem) detail.url = url

    return { ...o, detail }
  }

  if (input && Array.isArray(input.list)) {
    const items = input.list.map(transformOne)
    const join = k => input.list.map(o => String(o[k] || "")).join("\n")
    const summary = transformOne({ Count: items.length, Name: join("Name"),
      "File Extension": join("File Extension"), Base64: "" })
    return { list: items, detail: summary.detail }
  }
  return transformOne(input)
})
